"""Bases (suite) : épargne, placements, fiscalité, vocabulaire de l'investisseur et de la finance quantitative."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "bases"
TERMS = [
    d(T, "epargne_placement", "Épargne et placement", "Saving and investing", 1,
      "Épargner, c'est mettre de l'argent de côté ; placer, c'est le faire travailler pour qu'il rapporte. Plus un placement peut rapporter, plus il peut aussi perdre : l'épargne de précaution se garde sur des supports sûrs et disponibles, le reste se place selon l'horizon.",
      "Saving is setting money aside; investing is putting it to work so it earns. The more an investment can earn, the more it can also lose: emergency savings stay in safe, available vehicles, the rest is invested according to horizon.",
      see="horizon_placement risque_notion"),
    d(T, "patrimoine", "Patrimoine", "Wealth (net worth)", 1,
      "Ensemble de ce qu'on possède (épargne, titres, immobilier) moins ce qu'on doit (crédits). Sa répartition entre classes d'actifs détermine l'essentiel de son risque et de son rendement à long terme.",
      "All one owns (savings, securities, property) minus what one owes (loans). Its split among asset classes determines most of its long-run risk and return.",
      see="allocation_strategique_tactique wealth_summary"),
    d(T, "compte_titres", "Compte-titres et enveloppes fiscales", "Securities account and tax wrappers", 1,
      "Le compte-titres ordinaire permet d'acheter tous types de titres, avec une fiscalité de droit commun ; les enveloppes (PEA, assurance-vie, plans d'épargne retraite) offrent des avantages fiscaux en échange de contraintes de durée ou de produits éligibles.",
      "An ordinary securities account allows all types of securities, with standard taxation; wrappers (PEA, life insurance, retirement plans) offer tax advantages in exchange for holding-period or eligible-product constraints.",
      see="pea cto courtier"),
    d(T, "assurance_vie", "Assurance-vie", "Life-insurance savings contract", 1,
      "Contrat d'épargne français dont le capital peut être investi en fonds en euros (capital garanti) ou en unités de compte (supports en actions, ETF : sans garantie). Fiscalité allégée après 8 ans et avantages en cas de transmission.",
      "French savings contract whose capital can be invested in euro funds (guaranteed capital) or unit-linked funds (equity, ETF vehicles: no guarantee). Lighter taxation after 8 years and inheritance advantages.",
      see="compte_titres fonds_opcvm"),
    d(T, "livret_reglemente", "Livret réglementé", "Regulated savings account", 1,
      "Livret dont le taux est fixé par l'État (Livret A, LDDS, LEP), garanti, disponible à tout moment et défiscalisé. Il protège le capital mais son rendement réel peut être négatif quand l'inflation est élevée.",
      "Savings account whose rate is set by the state (Livret A, LDDS, LEP), guaranteed, available at any time and tax-free. It protects capital but its real return can be negative when inflation is high.",
      see="taux_nominal_reel inflation"),
    d(T, "immobilier_locatif", "Immobilier locatif et SCPI", "Rental property and property funds", 1,
      "L'immobilier rapporte des loyers et une éventuelle plus-value, avec un fort levier de crédit, mais il est illiquide, concentré et coûteux à acheter et vendre. Les SCPI donnent accès à un portefeuille d'immeubles sans gestion directe.",
      "Property earns rent and possible capital gain, with strong credit leverage, but is illiquid, concentrated and costly to buy and sell. Property funds (SCPI) give access to a building portfolio without direct management.",
      see="reit_siic levier liquidite"),
    d(T, "or_valeur_refuge", "Or et valeur refuge", "Gold and safe haven", 1,
      "L'or ne verse aucun revenu, mais il est perçu comme une protection en période d'inflation, de tensions géopolitiques ou de baisse du dollar. Sa corrélation avec les actions est faible, ce qui en fait un diversifieur, sans garantie.",
      "Gold pays no income, but is seen as protection in times of inflation, geopolitical tension or a weak dollar. Its correlation with equities is low, making it a diversifier, with no guarantee.",
      see="matiere_premiere diversification"),
    d(T, "valeur_refuge", "Valeur refuge", "Safe-haven asset", 1,
      "Actif dont on attend qu'il résiste ou monte quand les marchés chutent : emprunts d'État de qualité, or, franc suisse, yen. Ce statut n'est pas garanti : les obligations ont chuté avec les actions en 2022.",
      "Asset expected to hold up or rise when markets fall: quality government bonds, gold, Swiss franc, yen. The status is not guaranteed: bonds fell with equities in 2022.",
      see="or_valeur_refuge correlation_de_crise"),
    d(T, "plus_value_moins_value", "Plus-value et moins-value", "Capital gain and loss", 1,
      "Gain (ou perte) réalisé quand on vend un titre plus cher (ou moins cher) qu'on ne l'a acheté. Tant qu'on ne vend pas, on parle de plus-value latente. La fiscalité porte en général sur les plus-values réalisées.",
      "Gain (or loss) realised when selling a security above (or below) its purchase price. Until sold, it is an unrealised gain. Taxation generally applies to realised gains.",
      see="rendement fiscalite_placements"),
    d(T, "fiscalite_placements", "Fiscalité des placements", "Taxation of investments", 1,
      "Dividendes, intérêts et plus-values sont imposés selon des règles propres à chaque pays et enveloppe (en France, prélèvement forfaitaire de 30 % sur le compte-titres, régimes spécifiques PEA et assurance-vie). Les performances s'apprécient nettes d'impôts et de frais.",
      "Dividends, interest and capital gains are taxed under rules specific to each country and wrapper (in France, a 30% flat tax on securities accounts, specific PEA and life-insurance regimes). Performance is judged net of taxes and fees.",
      see="plus_value_moins_value compte_titres"),
    d(T, "frais_de_gestion", "Frais de gestion (TER)", "Management fees (TER)", 1,
      "Coût annuel d'un fonds, prélevé sur son actif : 0,1 % pour un ETF large, 1,5 à 2 % pour un fonds actif. Sur 30 ans, 1,5 point de frais en plus peut retirer un tiers du capital final : la seule composante du rendement sûre est ce qu'on ne paie pas.",
      "Annual cost of a fund, taken from its assets: 0.1% for a broad ETF, 1.5 to 2% for an active fund. Over 30 years, an extra 1.5 points of fees can remove a third of final capital: the only sure part of return is what one does not pay.",
      see="etf gestion_passive_active", alias="TER; frais courants"),
    d(T, "societe_de_gestion", "Société de gestion et gérant", "Asset manager and portfolio manager", 1,
      "La société de gestion crée et administre les fonds ; le gérant décide des achats et ventes. Elle est agréée et contrôlée par le régulateur (AMF en France) ; les titres du fonds sont conservés par un dépositaire indépendant.",
      "The management company creates and runs funds; the portfolio manager decides purchases and sales. It is licensed and supervised by the regulator (AMF in France); fund securities are held by an independent custodian.",
      see="fonds_opcvm gestion_passive_active"),
    d(T, "regulateur_marche", "Régulateur de marché", "Market regulator", 1,
      "Autorité qui supervise les marchés et les intermédiaires et protège les investisseurs : AMF en France, ESMA en Europe, SEC aux États-Unis. Elle impose la transparence (publication des résultats), sanctionne les abus (délit d'initié, manipulation).",
      "Authority supervising markets and intermediaries and protecting investors: AMF in France, ESMA in Europe, SEC in the US. It imposes transparency (earnings disclosure) and sanctions abuse (insider trading, manipulation).",
      see="delit_initie bourse"),
    d(T, "delit_initie", "Délit d'initié", "Insider trading", 1,
      "Utiliser une information privilégiée, non publique et précise, pour acheter ou vendre un titre avant qu'elle ne soit connue : c'est interdit et puni. La communication des résultats à tous en même temps vise à l'empêcher.",
      "Using precise, non-public privileged information to buy or sell a security before it becomes known: it is illegal and punished. Releasing results to everyone at the same time aims to prevent it.",
      see="regulateur_marche publication_resultats"),
    d(T, "valeur_nominale_marche", "Valeur nominale et valeur de marché", "Face value and market value", 1,
      "La valeur nominale est le montant inscrit sur le titre (1 000 € pour une obligation) ; la valeur de marché est le prix auquel il s'échange aujourd'hui, qui varie. À l'échéance, une obligation est remboursée à sa valeur nominale.",
      "Face value is the amount written on the security (€1,000 for a bond); market value is the price at which it trades today, which fluctuates. At maturity a bond is repaid at face value.",
      see="obligation prix_rendement_inverse"),
    d(T, "ticker_isin", "Symbole boursier (ticker) et code ISIN", "Ticker symbol and ISIN code", 1,
      "Le ticker est le symbole court d'une valeur sur une place (AAPL, MC.PA) ; l'ISIN est son code international unique à 12 caractères (FR0000121014). Un même titre a plusieurs tickers selon les places et sources de données : un piège classique d'alignement.",
      "The ticker is a security's short symbol on a venue (AAPL, MC.PA); the ISIN is its unique 12-character international code (FR0000121014). One security has several tickers across venues and data sources: a classic alignment trap.",
      see="bourse alignement_temporel"),
    d(T, "sous_jacent", "Sous-jacent", "Underlying", 1,
      "L'actif sur lequel porte un produit dérivé ou un fonds : l'action pour une option, l'indice pour un future ou un ETF. Le prix du dérivé en découle, d'où son nom.",
      "The asset a derivative or fund is based on: the share for an option, the index for a future or ETF. The derivative's price follows from it, hence the name.",
      see="option future"),
    d(T, "aversion_au_risque", "Aversion au risque (investisseur)", "Risk aversion (investor)", 1,
      "Préférence d'un investisseur pour un résultat certain plutôt qu'un pari de même espérance. Elle explique qu'on exige une prime de risque pour détenir des actions, et fixe le dosage entre actifs sûrs et risqués.",
      "An investor's preference for a certain outcome over a gamble with the same expectation. It explains why a risk premium is demanded to hold equities, and sets the mix of safe and risky assets.",
      see="prime_de_risque allocation_strategique_tactique"),
    d(T, "rendement_espere_realise", "Rendement espéré et rendement réalisé", "Expected and realised return", 1,
      "Le rendement espéré est ce qu'on attend en moyenne avant d'investir ; le réalisé est ce qu'on a obtenu après coup. L'écart est le hasard : sur un an, le réalisé d'un indice actions s'écarte souvent de 15 points de l'espéré.",
      "Expected return is what one expects on average before investing; realised is what was obtained afterwards. The gap is chance: over one year an equity index's realised return often departs by 15 points from the expected.",
      see="rendement volatilite"),
    d(T, "analyse_technique_fondamentale", "Analyse technique et analyse fondamentale", "Technical and fundamental analysis", 1,
      "L'analyse fondamentale évalue la valeur d'une entreprise par ses comptes et ses perspectives ; l'analyse technique lit l'historique des prix et des volumes (supports, moyennes mobiles). La finance quantitative teste les deux de façon systématique sur les données.",
      "Fundamental analysis assesses a company's value from its accounts and outlook; technical analysis reads price and volume history (supports, moving averages). Quantitative finance tests both systematically against data.",
      see="moyenne_mobile price_earnings finance_quantitative"),
    d(T, "finance_quantitative", "Finance quantitative (quant)", "Quantitative finance (quant)", 1,
      "Usage des mathématiques, des statistiques et de l'informatique pour valoriser des produits, mesurer le risque et construire des stratégies d'investissement fondées sur des règles testées plutôt que sur l'intuition. PATRICK relève de cette approche.",
      "Use of mathematics, statistics and computing to price products, measure risk and build investment strategies based on tested rules rather than intuition. PATRICK belongs to this approach.",
      see="backtest_notion signal_alpha", alias="quant; finance de marché quantitative"),
    d(T, "trading_algorithmique", "Trading algorithmique", "Algorithmic trading", 2,
      "Passage d'ordres décidé et exécuté par un programme selon des règles : de la simple règle de rééquilibrage aux stratégies de très haute fréquence. Il supprime l'émotion mais pas l'erreur de modèle.",
      "Order placement decided and executed by a program following rules: from a simple rebalancing rule to very-high-frequency strategies. It removes emotion but not model error.",
      see="algorithme_execution hft"),
    d(T, "investisseur_speculateur", "Investisseur, spéculateur, arbitragiste", "Investor, speculator, arbitrageur", 1,
      "L'investisseur détient pour le rendement de long terme, le spéculateur parie sur des variations de prix à court terme, l'arbitragiste exploite des écarts entre deux prix pour un gain quasi sans risque. Les marchés ont besoin des trois.",
      "The investor holds for long-term return, the speculator bets on short-term price moves, the arbitrageur exploits gaps between two prices for a near-riskless gain. Markets need all three.",
      see="arbitrage_pur"),
    d(T, "tendance_support_resistance", "Tendance, support et résistance", "Trend, support and resistance", 1,
      "En analyse technique, une tendance est une direction durable des prix ; un support est un niveau sous lequel les achats ont déjà stoppé des baisses, une résistance un niveau que la hausse peine à franchir. Notions intuitives, dont la valeur prédictive est discutée.",
      "In technical analysis a trend is a lasting price direction; support is a level where buying has previously halted declines, resistance a level the rise struggles to break. Intuitive notions whose predictive value is debated.",
      see="analyse_technique_fondamentale tendance_suivi"),
    d(T, "correction_rebond", "Correction et rebond", "Correction and rebound", 1,
      "Une correction est une baisse de 10 % ou plus depuis un sommet, moins profonde qu'un marché baissier (−20 %) ; un rebond est une remontée après une baisse. Ces mots décrivent le passé : on les reconnaît toujours après coup.",
      "A correction is a decline of 10% or more from a peak, shallower than a bear market (−20%); a rebound is a recovery after a fall. These words describe the past: they are only ever recognised afterwards.",
      see="marche_haussier_baissier krach"),
    d(T, "poids_position_exposition", "Poids, position et exposition", "Weight, position and exposure", 1,
      "Le poids est la part d'un actif dans le portefeuille ; la position est ce qu'on détient (longue ou courte) ; l'exposition est la sensibilité du portefeuille à un risque (marché, secteur, devise), qui peut dépasser le poids avec le levier.",
      "Weight is an asset's share of the portfolio; position is what one holds (long or short); exposure is the portfolio's sensitivity to a risk (market, sector, currency), which can exceed weight with leverage.",
      see="position_longue_courte exposition_brute_nette"),
    d(T, "classe_d_actifs", "Classe d'actifs", "Asset class", 1,
      "Grande famille d'actifs aux comportements proches : actions, obligations, liquidités, immobilier, matières premières, devises, crypto-actifs. La répartition entre classes explique l'essentiel de la variabilité d'un portefeuille.",
      "Broad family of assets behaving alike: equities, bonds, cash, real estate, commodities, currencies, crypto-assets. The split among classes explains most of a portfolio's variability.",
      see="allocation_strategique_tactique asset_equity"),
    d(T, "capital_risque_private_equity", "Capital-investissement (private equity)", "Private equity", 2,
      "Investissement dans des entreprises non cotées, peu liquide et à long terme (5 à 10 ans), avec des frais élevés. Ses rendements publiés sont lissés par des valorisations peu fréquentes, ce qui sous-estime sa volatilité apparente.",
      "Investment in unlisted companies, illiquid and long-term (5 to 10 years), with high fees. Its reported returns are smoothed by infrequent valuations, understating its apparent volatility.",
      see="liquidite sharpe_ajuste_autocorrelation"),
    d(T, "spread_notion_generale", "Spread (écart)", "Spread", 1,
      "Mot générique pour un écart entre deux prix ou taux : fourchette achat-vente, écart de crédit, écart entre deux taux souverains, écart entre deux actifs d'une stratégie de paires. Se lit toujours « de quoi par rapport à quoi ».",
      "Generic word for a gap between two prices or rates: bid–ask spread, credit spread, gap between two sovereign rates, gap between two assets in a pairs strategy. Always read as 'of what versus what'.",
      see="spread_bid_ask spread_de_credit spread_taux_pays"),
    d(T, "benchmark_indice_reference", "Indice de référence", "Reference index", 1,
      "Indice auquel on compare un placement pour juger s'il a fait mieux ou moins bien que le marché correspondant. Choisi à l'avance, il doit être investissable et pertinent : comparer un fonds d'actions européennes au S&P 500 n'a pas de sens.",
      "Index against which an investment is compared to judge whether it did better or worse than its market. Chosen in advance, it must be investable and relevant: comparing a European equity fund with the S&P 500 makes no sense.",
      see="benchmark benchmark_choix"),
    d(T, "inflation_et_epargne", "Inflation et épargne", "Inflation and savings", 1,
      "L'inflation érode le pouvoir d'achat de l'argent qui dort : 2 % par an réduit de moitié sa valeur réelle en 35 ans. D'où l'intérêt de placements dont le rendement dépasse l'inflation (actions, immobilier, obligations indexées).",
      "Inflation erodes the purchasing power of idle money: 2% a year halves its real value in 35 years. Hence the value of investments whose return exceeds inflation (equities, real estate, inflation-linked bonds).",
      see="inflation obligation_indexee"),
    d(T, "courbe_en_cloche_rendements", "Distribution des rendements", "Return distribution", 1,
      "Histogramme des rendements passés d'un actif : sa position dit le rendement typique, sa largeur la volatilité, sa forme (queues, asymétrie) le risque de gros mouvements. Les rendements réels ont plus d'extrêmes que la courbe en cloche.",
      "Histogram of an asset's past returns: its position gives the typical return, its width the volatility, its shape (tails, skew) the risk of large moves. Real returns have more extremes than the bell curve.",
      see="loi_normale queues_epaisses"),
    d(T, "regle_de_72", "Règle des 72", "Rule of 72", 1,
      "Approximation du temps de doublement d'un capital : 72 divisé par le taux annuel en pourcent. À 6 %, il double en 12 ans ; à 3 %, en 24 ans. La même règle donne la durée pour que l'inflation divise le pouvoir d'achat par deux.",
      "Approximation of the time for capital to double: 72 divided by the annual rate in percent. At 6% it doubles in 12 years; at 3%, in 24. The same rule gives the time for inflation to halve purchasing power.",
      formula=r"t \approx \frac{72}{r\,(\%)}", see="interet_compose"),
    d(T, "cotation_prix_achat_vente", "Cours acheteur, vendeur et dernier cours", "Bid, ask and last price", 1,
      "Le cours acheteur (bid) est le prix le plus haut qu'un acheteur propose ; le vendeur (ask) le plus bas qu'un vendeur accepte ; le dernier cours est celui de la dernière transaction, qui peut dater de plusieurs secondes ou minutes.",
      "The bid is the highest price a buyer offers; the ask the lowest a seller accepts; the last price is that of the most recent trade, which may be seconds or minutes old.",
      see="spread_bid_ask carnet_ordres"),
    d(T, "gestion_du_risque_individuelle", "Gérer son risque : règles simples", "Managing one's risk: simple rules", 1,
      "Ne pas investir ce dont on a besoin à court terme, diversifier, connaître la perte qu'on peut supporter avant d'acheter, ne pas emprunter pour spéculer, rééquilibrer régulièrement. Des règles banales qui évitent l'essentiel des catastrophes personnelles.",
      "Do not invest what is needed in the short term, diversify, know the loss one can bear before buying, do not borrow to speculate, rebalance regularly. Mundane rules that avoid most personal disasters.",
      see="diversification levier rebalancement"),
    d(T, "capitalisation_vs_distribution", "Fonds capitalisant et fonds distribuant", "Accumulating and distributing funds", 1,
      "Un fonds capitalisant réinvestit automatiquement les dividendes ; un distribuant les verse. À rendement égal avant impôt, la différence tient à la fiscalité et à la commodité ; les séries « rendement total » supposent la réinvestissement.",
      "An accumulating fund automatically reinvests dividends; a distributing one pays them out. At equal pre-tax return the difference is about taxation and convenience; 'total return' series assume reinvestment.",
      see="indice_prix_rendement_total etf"),
    d(T, "monnaie_de_compte_devise_base", "Devise de référence d'un portefeuille", "Portfolio base currency", 2,
      "Devise dans laquelle on mesure la performance (l'euro pour un investisseur européen). Un titre libellé en dollars a un rendement en euros égal à son rendement en dollars plus la variation du dollar contre l'euro, à combiner avec soin.",
      "Currency in which performance is measured (the euro for a European investor). A dollar-denominated security's euro return equals its dollar return plus the dollar's move against the euro, to be combined with care.",
      see="risque_change devise_change"),
    d(T, "illusion_monetaire", "Illusion monétaire et rendement réel composé", "Money illusion and compounded real return", 1,
      "Confondre euros courants et euros constants : un gain nominal de 30 % sur 10 ans avec 3 % d'inflation par an est un gain réel d'environ 0 %. Comparer des séries longues exige de les déflater.",
      "Confusing current and constant euros: a nominal gain of 30% over 10 years with 3% annual inflation is a real gain of about 0%. Comparing long series requires deflating them.",
      see="taux_nominal_reel inflation"),
]
